ALTER TABLE articles ADD COLUMN IF NOT EXISTS meta_title           TEXT;
ALTER TABLE articles ADD COLUMN IF NOT EXISTS meta_description     TEXT;
ALTER TABLE articles ADD COLUMN IF NOT EXISTS body_withdrawn       TEXT;
ALTER TABLE articles ADD COLUMN IF NOT EXISTS source_url_withdrawn TEXT;

